insert into public.catalog_products (code, name, category_id, product_format, pack, description, ingredients, review_status, internal_notes, sources, sort_order)
select v.code, v.name, c.id, v.format::public.product_format, v.pack, null, v.ingredients::jsonb, v.status, v.notes, v.sources, v.sort_order
  from (values
  ('NEW-001', 'Magnesium Bisglycinate Powder', 'Essential Nutrients & Core Actives', 'powder', '1 measured serving', '[{"name":"Magnesium","amount":"200 mg","spec":"Magnesium bisglycinate; assay and buffered/unbuffered identity to verify","basis":"elemental mineral"}]', 'draft_formulation', 'При 14% Mg: 1428,6 mg суровина; пример, не потвърдена спецификация. Провери дали EN101 вече има прахообразен вариант. Не наричай буфериран оксиден продукт pure bisglycinate.', null, 2010),
  ('NEW-002', 'Thiamine B1', 'Essential Nutrients & Core Actives', 'capsule', '1 capsule', '[{"name":"Vitamin B1","amount":"100 mg","spec":"Thiamine hydrochloride","basis":"active vitamin"}]', 'draft_formulation', 'Предложение 100 mg вместо първоначалните 500 mg; промяната е за одобрение. Не е дневна хранителна потребност.', null, 2020),
  ('NEW-003', 'Niacinamide B3', 'Essential Nutrients & Core Actives', 'capsule', '1 capsule', '[{"name":"Vitamin B3","amount":"100 mg","spec":"Nicotinamide, not nicotinic acid","basis":"active vitamin"}]', 'draft_formulation', 'Предложение 100 mg вместо първоначалните 500 mg; промяната е за одобрение.', null, 2030),
  ('NEW-004', 'Biotin', 'Essential Nutrients & Core Actives', 'capsule', '1 capsule', '[{"name":"Biotin","amount":"1000 mcg","spec":"D-biotin diluted premix","basis":"active vitamin"}]', 'draft_formulation', 'Предложение 1000 ug вместо 10000 ug. Предупреждение за лабораторни интерференции; уведомяване на лекар/лаборатория. Не обещава растеж на коса при липса на дефицит.', 'S03 NIH ODS Biotin: https://ods.od.nih.gov/factsheets/Biotin-HealthProfessional/', 2040),
  ('NEW-005', 'Methylfolate', 'Essential Nutrients & Core Actives', 'capsule', '1 capsule', '[{"name":"Folate","amount":"400 mcg","spec":"Calcium L-methylfolate; stated folate content","basis":"active vitamin"}]', 'draft_formulation', 'Масата на солта и носителя се изчислява по assay.', null, 2050),
  ('NEW-006', 'Premium Methylated B-Complex', 'Essential Nutrients & Core Actives', 'capsule', '1 capsule', '[{"name":"Vitamin B1","amount":"10 mg","spec":"Thiamine hydrochloride","basis":"active vitamin"},{"name":"Vitamin B2","amount":"5 mg","spec":"Riboflavin-5-phosphate sodium","basis":"active vitamin"},{"name":"Vitamin B3","amount":"30 mg","spec":"Nicotinamide","basis":"active vitamin"},{"name":"Vitamin B5","amount":"20 mg","spec":"Calcium D-pantothenate","basis":"active vitamin"},{"name":"Vitamin B6","amount":"3 mg","spec":"Pyridoxal-5-phosphate","basis":"active vitamin"},{"name":"Biotin","amount":"100 mcg","spec":"D-biotin","basis":"active vitamin"},{"name":"Folate","amount":"400 mcg","spec":"Calcium L-methylfolate","basis":"active vitamin"},{"name":"Vitamin B12","amount":"100 mcg","spec":"Methylcobalamin","basis":"active vitamin"}]', 'draft_formulation', 'Метилирани са B12 и фолатът; не всички витамини. Отчита се B6 от всички други продукти.', 'S01 EFSA B6 UL (2023): https://efsa.onlinelibrary.wiley.com/doi/10.2903/j.efsa.2023.8006', 2060),
  ('NEW-007', 'Men’s Multivitamin', 'Essential Nutrients & Core Actives', 'capsule', 'Target: 2 capsules; pilot fill required', '[{"name":"Vitamin A","amount":"400 mcg RE","spec":"Retinyl acetate","basis":"active vitamin"},{"name":"Vitamin C","amount":"120 mg","spec":"Ascorbic acid","basis":"active vitamin"},{"name":"Vitamin D3","amount":"25 mcg","spec":"Cholecalciferol","basis":"active vitamin"},{"name":"Vitamin E","amount":"12 mg alpha-TE","spec":"D-alpha-tocopheryl acetate; activity conversion required","basis":"active vitamin"},{"name":"Vitamin K2","amount":"75 mcg","spec":"Menaquinone-7; all-trans assay","basis":"active vitamin"},{"name":"Vitamin B1","amount":"2.2 mg","spec":"Thiamine hydrochloride","basis":"active vitamin"},{"name":"Vitamin B2","amount":"2.8 mg","spec":"Riboflavin","basis":"active vitamin"},{"name":"Vitamin B3","amount":"16 mg","spec":"Nicotinamide","basis":"active vitamin"},{"name":"Vitamin B5","amount":"6 mg","spec":"Calcium D-pantothenate","basis":"active vitamin"},{"name":"Vitamin B6","amount":"2 mg","spec":"Pyridoxal-5-phosphate","basis":"active vitamin"},{"name":"Folate","amount":"200 mcg","spec":"Calcium L-methylfolate","basis":"active vitamin"},{"name":"Vitamin B12","amount":"25 mcg","spec":"Methylcobalamin","basis":"active vitamin"},{"name":"Biotin","amount":"50 mcg","spec":"D-biotin","basis":"active vitamin"},{"name":"Magnesium","amount":"50 mg","spec":"Magnesium bisglycinate","basis":"elemental mineral"},{"name":"Zinc","amount":"10 mg","spec":"Zinc bisglycinate","basis":"elemental mineral"},{"name":"Selenium","amount":"55 mcg","spec":"L-selenomethionine","basis":"elemental mineral"},{"name":"Iodine","amount":"75 mcg","spec":"Potassium iodide","basis":"elemental mineral"},{"name":"Copper","amount":"0.5 mg","spec":"Copper gluconate","basis":"elemental mineral"},{"name":"Manganese","amount":"1 mg","spec":"Manganese citrate","basis":"elemental mineral"}]', 'draft_formulation', 'За възрастни мъже; витамин K при антикоагуланти и йод при заболяване на щитовидната жлеза изискват преглед.', 'S01 EFSA B6 UL (2023): https://efsa.onlinelibrary.wiley.com/doi/10.2903/j.efsa.2023.8006', 2070),
  ('NEW-008', 'Women’s Multivitamin', 'Essential Nutrients & Core Actives', 'capsule', 'Target: 2 capsules; pilot fill required', '[{"name":"Vitamin A","amount":"400 mcg RE","spec":"Retinyl acetate","basis":"active vitamin"},{"name":"Vitamin C","amount":"120 mg","spec":"Ascorbic acid","basis":"active vitamin"},{"name":"Vitamin D3","amount":"25 mcg","spec":"Cholecalciferol","basis":"active vitamin"},{"name":"Vitamin E","amount":"12 mg alpha-TE","spec":"D-alpha-tocopheryl acetate; activity conversion required","basis":"active vitamin"},{"name":"Vitamin K2","amount":"75 mcg","spec":"Menaquinone-7; all-trans assay","basis":"active vitamin"},{"name":"Vitamin B1","amount":"2.2 mg","spec":"Thiamine hydrochloride","basis":"active vitamin"},{"name":"Vitamin B2","amount":"2.8 mg","spec":"Riboflavin","basis":"active vitamin"},{"name":"Vitamin B3","amount":"16 mg","spec":"Nicotinamide","basis":"active vitamin"},{"name":"Vitamin B5","amount":"6 mg","spec":"Calcium D-pantothenate","basis":"active vitamin"},{"name":"Vitamin B6","amount":"2 mg","spec":"Pyridoxal-5-phosphate","basis":"active vitamin"},{"name":"Folate","amount":"400 mcg","spec":"Calcium L-methylfolate","basis":"active vitamin"},{"name":"Vitamin B12","amount":"25 mcg","spec":"Methylcobalamin","basis":"active vitamin"},{"name":"Biotin","amount":"50 mcg","spec":"D-biotin","basis":"active vitamin"},{"name":"Magnesium","amount":"50 mg","spec":"Magnesium bisglycinate","basis":"elemental mineral"},{"name":"Zinc","amount":"8 mg","spec":"Zinc bisglycinate","basis":"elemental mineral"},{"name":"Selenium","amount":"55 mcg","spec":"L-selenomethionine","basis":"elemental mineral"},{"name":"Iodine","amount":"75 mcg","spec":"Potassium iodide","basis":"elemental mineral"},{"name":"Copper","amount":"0.5 mg","spec":"Copper gluconate","basis":"elemental mineral"},{"name":"Manganese","amount":"1 mg","spec":"Manganese citrate","basis":"elemental mineral"},{"name":"Iron","amount":"7 mg","spec":"Ferrous bisglycinate","basis":"elemental mineral"}]', 'draft_formulation', 'Версия за менструиращи възрастни жени; не пренатална. За универсална/следменопаузална версия преоцени желязото. Не комбинирай автоматично с Female Fertility.', 'S01 EFSA B6 UL (2023): https://efsa.onlinelibrary.wiley.com/doi/10.2903/j.efsa.2023.8006
S04 NIH ODS Folate: https://ods.od.nih.gov/factsheets/Folate-HealthProfessional/', 2080),
  ('NEW-009', 'Bulgarian Tribulus Terrestris Extract', 'Essential Nutrients & Core Actives', 'capsule', 'Target: 2 capsules', '[{"name":"Tribulus terrestris extract","amount":"500 mg","spec":"Target 95% total saponins; plant part, Bulgarian origin, extraction and assay method unresolved","basis":"extract mass"}]', 'draft_formulation', '95% не се приема без COA и метод; различните сапонинови анализи не са взаимозаменяеми. Не е доказан testosterone booster.', null, 2090),
  ('NEW-010', 'Milk Thistle Extract', 'Essential Nutrients & Core Actives', 'capsule', 'Target: 1–2 capsules', '[{"name":"Milk thistle fruit extract","amount":"300 mg","spec":"Silybum marianum; target 80% silymarin; assay method required","basis":"extract mass"}]', 'draft_formulation', 'Целево 240 mg silymarin, ако 80% са потвърдени.', null, 2100),
  ('NEW-011', 'Curcumin Extract', 'Essential Nutrients & Core Actives', 'capsule', 'Target: 1–2 capsules', '[{"name":"Turmeric rhizome extract","amount":"500 mg","spec":"Curcuma longa; 95% total curcuminoids","basis":"extract mass"}]', 'draft_formulation', 'Целево 475 mg curcuminoids. Без пиперин. Преглед при жлъчни проблеми, чернодробни заболявания и лекарства.', null, 2110),
  ('NEW-012', 'Multi-Source Collagen Complex', 'Collagen Products', 'powder', '1 measured serving', '[{"name":"Hydrolyzed bovine collagen peptides","amount":"7000 mg","spec":"Food-grade; source and peptide profile to verify","basis":"ingredient mass"},{"name":"Hydrolyzed marine collagen peptides","amount":"2000 mg","spec":"Fish source; species and allergen statement required","basis":"ingredient mass"},{"name":"Hydrolyzed chicken collagen peptides","amount":"1000 mg","spec":"Hydrolyzed; not undenatured type II","basis":"ingredient mass"},{"name":"Vitamin C","amount":"100 mg","spec":"Ascorbic acid","basis":"active vitamin"},{"name":"Hyaluronic acid","amount":"100 mg","spec":"Sodium hyaluronate; calculate acid-equivalent assay","basis":"active compound"}]', 'draft_formulation', '10 g колагенови суровини, 5 активки. Риба като алерген. Без твърдение за всички типове колаген или клинично превъзходство.', null, 2120),
  ('NEW-013', 'Female Fertility Support', 'Women’s Health', null, 'Powder / sachets: Total daily formula divided into 2 servings', '[{"name":"Myo-inositol","amount":"4000 mg","spec":"Identity and purity specification","basis":"ingredient mass"},{"name":"Folic acid","amount":"400 mcg","spec":"Pteroylmonoglutamic acid","basis":"active vitamin"},{"name":"Vitamin D3","amount":"20 mcg","spec":"Cholecalciferol","basis":"active vitamin"},{"name":"Vitamin B12","amount":"10 mcg","spec":"Methylcobalamin","basis":"active vitamin"},{"name":"Vitamin B6","amount":"1.4 mg","spec":"Pyridoxal-5-phosphate","basis":"active vitamin"},{"name":"Zinc","amount":"5 mg","spec":"Zinc bisglycinate","basis":"elemental mineral"}]', 'draft_formulation', 'Предконцепционна нутритивна разработка, не универсално лечение на инфертилитет или пълен prenatal. Без обещание за зачеване; преглед при бременност и съпътстващи добавки.', 'S04 NIH ODS Folate: https://ods.od.nih.gov/factsheets/Folate-HealthProfessional/', 2130),
  ('NEW-014', 'Menopause Support', 'Women’s Health', 'capsule', 'Target: 3 capsules', '[{"name":"Saffron stigma extract","amount":"30 mg","spec":"Crocus sativus; target >=3% crocins by HPLC; safranal specification required","basis":"extract mass"},{"name":"Lemon balm leaf extract","amount":"200 mg","spec":"Melissa officinalis; aqueous native DER 4:1 target","basis":"extract mass"},{"name":"Magnesium","amount":"100 mg","spec":"Magnesium bisglycinate","basis":"elemental mineral"},{"name":"Vitamin B6","amount":"1.4 mg","spec":"Pyridoxal-5-phosphate","basis":"active vitamin"},{"name":"Vitamin D3","amount":"25 mcg","spec":"Cholecalciferol","basis":"active vitamin"}]', 'draft_formulation', 'Генеричен шафран; няма доказана еквивалентност с брандиран изследван екстракт. Фокус настроение/комфорт, не хормонозаместителна терапия.', 'S05 Saffron perimenopause RCT: https://pmc.ncbi.nlm.nih.gov/articles/PMC8408316/', 2140),
  ('NEW-015', 'Male Libido Support', 'Men’s Health & Sexual Wellness', 'capsule', 'Target: 3 capsules', '[{"name":"Tribulus terrestris extract","amount":"500 mg","spec":"Same approved botanical specification as standalone product; assay pending","basis":"extract mass"},{"name":"Panax ginseng root extract","amount":"200 mg","spec":"5% total ginsenosides; HPLC method","basis":"extract mass"},{"name":"Ginger rhizome extract","amount":"100 mg","spec":"Zingiber officinale; 5% gingerols","basis":"extract mass"},{"name":"Saffron stigma extract","amount":"30 mg","spec":"Crocus sativus; target >=3% crocins by HPLC","basis":"extract mass"},{"name":"Zinc","amount":"10 mg","spec":"Zinc bisglycinate","basis":"elemental mineral"}]', 'draft_formulation', 'Различен от Testosterone Support. Преглед при антикоагуланти, диабетни лекарства и психотропни лекарства. Без обещан ефект върху ерекция/тестостерон.', null, 2150),
  ('NEW-016', 'Sexual Performance Support', 'Men’s Health & Sexual Wellness', 'powder', '1 measured serving', '[{"name":"L-Citrulline","amount":"3000 mg","spec":"Free L-citrulline, not citrulline malate","basis":"ingredient mass"},{"name":"L-Arginine","amount":"1500 mg","spec":"Free base","basis":"ingredient mass"},{"name":"Panax ginseng root extract","amount":"200 mg","spec":"5% total ginsenosides","basis":"extract mass"},{"name":"Pine bark extract","amount":"100 mg","spec":"Pinus pinaster; target 65% procyanidins; analytical method required","basis":"extract mass"},{"name":"Vitamin C","amount":"100 mg","spec":"Ascorbic acid","basis":"active vitamin"}]', 'draft_formulation', 'Не е еквивалент на sildenafil. Нитрати, антихипертензивни и PDE5 инхибитори изискват лекарствен преглед. Генерична борова кора не е автоматично еквивалентна на брандирана.', null, 2160),
  ('NEW-017', 'Male Fertility Support', 'Men’s Health & Sexual Wellness', null, 'Powder / sachet: 1 measured daily serving', '[{"name":"L-Carnitine","amount":"1000 mg","spec":"From L-carnitine L-tartrate; calculate salt mass","basis":"active compound"},{"name":"Coenzyme Q10","amount":"100 mg","spec":"Ubiquinone; dispersible premix for powder","basis":"active compound"},{"name":"Vitamin C","amount":"200 mg","spec":"Ascorbic acid","basis":"active vitamin"},{"name":"Zinc","amount":"10 mg","spec":"Zinc bisglycinate","basis":"elemental mineral"},{"name":"Selenium","amount":"55 mcg","spec":"L-selenomethionine","basis":"elemental mineral"},{"name":"Folate","amount":"200 mcg","spec":"Calcium L-methylfolate","basis":"active vitamin"}]', 'draft_formulation', 'Не обещава бременност или раждаемост. MOXI не установява полза на изследваната антиоксидантна комбинация върху основни показатели. Нашата комбинация също не е изпитана.', 'S06 MOXI trial: https://pubmed.ncbi.nlm.nih.gov/32111479/', 2170),
  ('NEW-018', 'Gut Barrier Support', 'Digestive & Gut Health', 'powder', '1 measured daily serving', '[{"name":"L-Glutamine","amount":"5000 mg","spec":"Food-grade","basis":"ingredient mass"},{"name":"Glycine","amount":"1000 mg","spec":"Food-grade","basis":"ingredient mass"},{"name":"PHGG","amount":"2000 mg","spec":"Partially hydrolyzed guar gum; fibre assay","basis":"ingredient mass"},{"name":"Zinc","amount":"5 mg","spec":"Zinc bisglycinate","basis":"elemental mineral"},{"name":"Vitamin D3","amount":"10 mcg","spec":"Cholecalciferol","basis":"active vitamin"}]', 'draft_formulation', 'Без zinc L-carnosine. Не е доказано лечение на leaky gut; оценка на поносимост и микродозовата хомогенност.', 'S07 EFSA zinc L-carnosine 2026: https://efsa.onlinelibrary.wiley.com/doi/10.2903/j.efsa.2026.10144', 2180),
  ('NEW-019', 'Gas & Bloating Support', 'Digestive & Gut Health', 'capsule', 'Target: 2–3 capsules', '[{"name":"Peppermint leaf extract","amount":"200 mg","spec":"Mentha x piperita; aqueous native DER 4:1 target","basis":"extract mass"},{"name":"Lemon balm leaf extract","amount":"150 mg","spec":"Melissa officinalis; aqueous native DER 4:1 target","basis":"extract mass"},{"name":"Caraway fruit extract","amount":"150 mg","spec":"Carum carvi; aqueous native DER 4:1 target","basis":"extract mass"},{"name":"Chamomile flower extract","amount":"150 mg","spec":"Matricaria recutita; aqueous native DER 4:1 target","basis":"extract mass"},{"name":"Ginger rhizome extract","amount":"100 mg","spec":"5% gingerols","basis":"extract mass"}]', 'draft_formulation', 'Мента може да влоши рефлукс. Asteraceae алергии при лайка. Екстрактите и целият комплекс не са еквивалент на лекарствени ментови препарати.', 'S08 EMA peppermint leaf: https://www.ema.europa.eu/en/medicines/herbal/menthae-piperitae-folium', 2190),
  ('NEW-020', 'Gut Comfort Complex', 'Digestive & Gut Health', 'powder', '1 measured daily serving; tolerance titration needed', '[{"name":"PHGG","amount":"5000 mg","spec":"Partially hydrolyzed guar gum; fibre assay","basis":"ingredient mass"},{"name":"Psyllium husk powder","amount":"1500 mg","spec":"Plantago ovata husk","basis":"ingredient mass"},{"name":"Lemon balm leaf extract","amount":"150 mg","spec":"Melissa officinalis; aqueous native DER 4:1 target","basis":"extract mass"},{"name":"Ginger rhizome extract","amount":"100 mg","spec":"5% gingerols","basis":"extract mass"},{"name":"Zinc","amount":"5 mg","spec":"Zinc bisglycinate","basis":"elemental mineral"}]', 'draft_formulation', 'Работната IBS концепция. Не е универсална за всички IBS подтипове; достатъчно вода и раздалечаване от лекарства. Данните за PHGG не доказват цялата смес.', 'S09 PHGG IBS RCT: https://pubmed.ncbi.nlm.nih.gov/26855665/', 2200),
  ('NEW-021', 'Bowel Regularity & Fibre Complex', 'Digestive & Gut Health', 'powder', '9 g blend/day, divided if required', '[{"name":"Psyllium husk powder","amount":"4000 mg","spec":"Plantago ovata husk","basis":"ingredient mass"},{"name":"PHGG","amount":"2000 mg","spec":"Partially hydrolyzed guar gum","basis":"ingredient mass"},{"name":"Acacia fibre","amount":"1000 mg","spec":"Acacia senegal/seyal gum; species and fibre assay","basis":"ingredient mass"},{"name":"Stabilized milled flaxseed","amount":"1000 mg","spec":"Linum usitatissimum; cyanogenic glycoside limits and oxidation specification","basis":"ingredient mass"},{"name":"Apple pectin","amount":"1000 mg","spec":"Food-grade pectin","basis":"ingredient mass"}]', 'draft_formulation', '9 g смес не означава 9 g аналитични фибри. Достатъчно вода; да не се приема сухо; не при затруднено преглъщане/обструкция. Ленът изисква стабилност и контрол на цианогенни съединения.', null, 2210),
  ('NEW-022', 'Appetite Support Formula', 'Digestive & Gut Health', 'capsule', 'Target: 3 capsules', '[{"name":"Gentian root powder","amount":"600 mg","spec":"Gentiana lutea; identity and bitter-value specification","basis":"ingredient mass"},{"name":"Dandelion root extract","amount":"150 mg","spec":"Taraxacum officinale; aqueous native DER 4:1 target","basis":"extract mass"},{"name":"Lemon balm leaf extract","amount":"150 mg","spec":"Melissa officinalis; aqueous native DER 4:1 target","basis":"extract mass"},{"name":"Ginger rhizome extract","amount":"100 mg","spec":"5% gingerols","basis":"extract mass"},{"name":"Zinc","amount":"5 mg","spec":"Zinc bisglycinate","basis":"elemental mineral"}]', 'draft_formulation', 'Стимулиране на апетита, не Appetite Control. Предварителна концепция; преглед при язва, рефлукс и жлъчни проблеми. Не копирай medicinal claims от EMA.', 'S10 EMA gentian root: https://www.ema.europa.eu/en/medicines/herbal/gentianae-radix', 2220),
  ('NEW-023', 'Vein & Circulation Support', 'Heart & Circulation', 'capsule', 'Target: 2–3 capsules', '[{"name":"Red vine leaf extract","amount":"360 mg","spec":"Vitis vinifera; aqueous native DER 4–6:1","basis":"extract mass"},{"name":"Rutin","amount":"100 mg","spec":"Identity and purity assay","basis":"active compound"},{"name":"Grape seed extract","amount":"100 mg","spec":"Vitis vinifera; target 90% proanthocyanidins; method required","basis":"extract mass"},{"name":"Vitamin C","amount":"100 mg","spec":"Ascorbic acid","basis":"active vitamin"},{"name":"Manganese","amount":"1 mg","spec":"Manganese citrate","basis":"elemental mineral"}]', 'draft_formulation', 'Данните за конкретни препарати от лозов лист не доказват комбинираната добавка. Преглед при антикоагуланти.', 'S11 EMA red vine leaf: https://www.ema.europa.eu/en/medicines/herbal/vitis-viniferae-folium', 2230),
  ('NEW-024', 'Heart Support Complex', 'Heart & Circulation', 'capsule', 'Target: 4 capsules', '[{"name":"Taurine","amount":"500 mg","spec":"Food-grade","basis":"ingredient mass"},{"name":"Coenzyme Q10","amount":"100 mg","spec":"Ubiquinone","basis":"active compound"},{"name":"Magnesium","amount":"100 mg","spec":"Magnesium bisglycinate","basis":"elemental mineral"},{"name":"Vitamin C","amount":"80 mg","spec":"Ascorbic acid","basis":"active vitamin"},{"name":"Vitamin B1","amount":"1.1 mg","spec":"Thiamine hydrochloride","basis":"active vitamin"}]', 'draft_formulation', 'Различен от Blood Pressure Support. Лекарствен преглед при сърдечна терапия/warfarin; магнезият изисква внимание при бъбречно увреждане.', null, 2240),
  ('NEW-025', 'Bone Health Formula', 'Bones, Joints & Mobility', null, 'Capsules or powder: Target: 4 capsules or measured powder', '[{"name":"Calcium","amount":"300 mg","spec":"Calcium carbonate","basis":"elemental mineral"},{"name":"Magnesium","amount":"100 mg","spec":"Magnesium bisglycinate","basis":"elemental mineral"},{"name":"Vitamin D3","amount":"25 mcg","spec":"Cholecalciferol","basis":"active vitamin"},{"name":"Vitamin K2","amount":"75 mcg","spec":"Menaquinone-7; all-trans assay","basis":"active vitamin"},{"name":"Zinc","amount":"5 mg","spec":"Zinc bisglycinate","basis":"elemental mineral"}]', 'draft_formulation', 'Ca 300 mg изисква около 750 mg carbonate при 40% assay. Vitamin K при антагонисти на витамин K; преглед при бъбречно заболяване/хиперкалциемия.', null, 2250),
  ('NEW-026', 'Uric Acid Balance Complex', 'Bones, Joints & Mobility', 'capsule', 'Target: 3 capsules', '[{"name":"Tart cherry fruit extract","amount":"500 mg","spec":"Prunus cerasus; native DER 10:1 target; anthocyanin assay pending","basis":"extract mass"},{"name":"Quercetin","amount":"200 mg","spec":"Identity and purity assay","basis":"active compound"},{"name":"Vitamin C","amount":"200 mg","spec":"Ascorbic acid","basis":"active vitamin"},{"name":"Celery seed extract","amount":"100 mg","spec":"Apium graveolens; native DER 4:1 target","basis":"extract mass"},{"name":"Folate","amount":"200 mcg","spec":"Calcium L-methylfolate","basis":"active vitamin"}]', 'concept_review', 'Ограничена обосновка за готовия комплекс. Не е лечение на подагра. Фолатът е допълващ нутриент, не доказан уратопонижаващ агент. Целина: алерген; изключване при бременност без индивидуална оценка.', null, 2260),
  ('NEW-027', 'Eye Support Complex', 'Targeted Health Formulas', 'capsule', 'Target: 2 capsules', '[{"name":"Lutein","amount":"10 mg","spec":"Stabilized beadlets; active assay","basis":"active compound"},{"name":"Zeaxanthin","amount":"2 mg","spec":"Stabilized beadlets; active assay","basis":"active compound"},{"name":"Vitamin C","amount":"100 mg","spec":"Ascorbic acid","basis":"active vitamin"},{"name":"Vitamin E","amount":"12 mg alpha-TE","spec":"D-alpha-tocopheryl acetate","basis":"active vitamin"},{"name":"Zinc","amount":"5 mg","spec":"Zinc bisglycinate","basis":"elemental mineral"},{"name":"Copper","amount":"0.5 mg","spec":"Copper gluconate","basis":"elemental mineral"},{"name":"Vitamin B2","amount":"1.4 mg","spec":"Riboflavin","basis":"active vitamin"}]', 'draft_formulation', 'Не е AREDS2; не приписвай резултати за AMD на тази различна формула.', 'S12 NEI AREDS2 FAQ: https://www.nei.nih.gov/eye-health-information/clinical-trials/age-related-eye-disease-studies-aredsareds2/aredsareds2-frequently-asked-questions', 2270),
  ('NEW-028', 'Urinary Tract Support', 'Targeted Health Formulas', 'capsule', 'Target: 3 capsules', '[{"name":"Cranberry extract","amount":"360 mg","spec":"Vaccinium macrocarpon; 10% PAC by BL-DMAC = 36 mg PAC","basis":"extract mass"},{"name":"Pumpkin seed extract","amount":"300 mg","spec":"Cucurbita pepo; aqueous native DER 4:1 target","basis":"extract mass"},{"name":"Hibiscus calyx extract","amount":"200 mg","spec":"Hibiscus sabdariffa; aqueous native DER 4:1 target","basis":"extract mass"},{"name":"Vitamin C","amount":"80 mg","spec":"Ascorbic acid","basis":"active vitamin"},{"name":"Zinc","amount":"5 mg","spec":"Zinc bisglycinate","basis":"elemental mineral"}]', 'draft_formulation', 'Не е терапия на инфекция или бъбречна недостатъчност. D-mannose не е включена. Изследване на цялата смес липсва; преглед при ниско кръвно, лекарства и бременност.', 'S13 D-mannose RCT 2024: https://pubmed.ncbi.nlm.nih.gov/38587819/', 2280),
  ('NEW-029', 'Lung & Respiratory Support', 'Targeted Health Formulas', 'capsule', 'Target: 3 capsules', '[{"name":"Mullein flower extract","amount":"300 mg","spec":"Verbascum thapsus; aqueous native DER 4:1 target","basis":"extract mass"},{"name":"Marshmallow root extract","amount":"300 mg","spec":"Althaea officinalis; aqueous native DER 4:1 target","basis":"extract mass"},{"name":"Thyme herb extract","amount":"200 mg","spec":"Thymus vulgaris; aqueous native DER 4:1 target","basis":"extract mass"},{"name":"Vitamin C","amount":"160 mg","spec":"Ascorbic acid","basis":"active vitamin"},{"name":"Zinc","amount":"5 mg","spec":"Zinc bisglycinate","basis":"elemental mineral"}]', 'draft_formulation', 'Билкова концепция; оценка дали капсулите са подходящи за предвиденото действие. Не възстановява увреждания от пушене и не замества терапия при белодробно заболяване.', null, 2290),
  ('NEW-030', 'NAD+ Support Complex', 'Longevity & Cellular Health', 'capsule', 'Target: 2–3 capsules', '[{"name":"Nicotinamide riboside chloride","amount":"300 mg","spec":"Must conform to applicable EU authorised specifications","basis":"ingredient mass"},{"name":"Trimethylglycine","amount":"300 mg","spec":"Anhydrous betaine; not betaine HCl","basis":"ingredient mass"},{"name":"Coenzyme Q10","amount":"100 mg","spec":"Ubiquinone","basis":"active compound"},{"name":"Vitamin B2","amount":"1.4 mg","spec":"Riboflavin","basis":"active vitamin"},{"name":"Vitamin B6","amount":"1.4 mg","spec":"Pyridoxal-5-phosphate","basis":"active vitamin"}]', 'supplier_review', 'За възрастни; изключени бременни/кърмещи за тази версия. Без apigenin до проверка. Генерична NR суровина не е автоматично съответстваща. Не е доказано удължаване на живота.', 'S02 EU NR chloride conditions: https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=celex%3A32022R1160', 2300),
  ('NEW-031', 'Cellular Polyphenol Complex', 'Longevity & Cellular Health', 'capsule', 'Target: 2–3 capsules', '[{"name":"Quercetin","amount":"250 mg","spec":"Identity and purity assay","basis":"active compound"},{"name":"Trans-resveratrol","amount":"100 mg","spec":"Source, purity and applicable conditions to verify","basis":"active compound"},{"name":"Grape seed extract","amount":"100 mg","spec":"Target 90% proanthocyanidins; assay method required","basis":"extract mass"},{"name":"Vitamin C","amount":"100 mg","spec":"Ascorbic acid","basis":"active vitamin"},{"name":"Selenium","amount":"55 mcg","spec":"L-selenomethionine","basis":"elemental mineral"}]', 'draft_formulation', 'Отделен продукт от Senolytic Complex. Не твърди сенолиза. Проверка на ресвератролния източник и взаимодействия, особено антикоагуланти.', null, 2310),
  ('NEW-032', 'Urolithin A', 'Longevity & Cellular Health', 'capsule', 'Target: 2 capsules; research dose only', '[{"name":"Urolithin A","amount":"500 mg","spec":"Qualified source, purity, legal basis and study-material comparability unresolved","basis":"active compound"}]', 'supplier_review', '500 mg е изследвана доза, не потвърдена готовност за продажба. Не е потвърдено приложимо EU разрешение за конкретния доставчик.', 'S14 EU Urolithin A application: https://food.ec.europa.eu/document/download/8f10d273-65cb-4450-85cb-4bf389d8670c_en?filename=novel-food_sum_ongoing-app_2018-0538.pdf
S15 Urolithin A human RCT: https://pubmed.ncbi.nlm.nih.gov/35584623/', 2320),
  ('NEW-033', 'Creatine HCl Capsules', 'Sport & Performance Nutrition', 'capsule', '4 capsules/day; 750 mg creatine HCl per capsule', '[{"name":"Creatine hydrochloride","amount":"3000 mg","spec":"Identity, assay and market status to verify","basis":"ingredient mass"}]', 'supplier_review', '3000 mg HCl сол доставя приблизително 2350 mg креатин; не 3000 mg. Не твърди еквивалентност на 750 mg HCl с 3 g monohydrate. Проба за капсулен обем.', 'S16 AESAN creatine assessment: https://efsa.onlinelibrary.wiley.com/doi/epdf/10.2903/fr.efsa.2024.FR-0046', 2330),
  ('NEW-034', 'Cellular Energy & Performance', 'Sport & Performance Nutrition', 'powder', '1 measured daily serving', '[{"name":"Creatine monohydrate","amount":"3410 mg","spec":"Approx. 3000 mg creatine; assay conversion required","basis":"ingredient mass"},{"name":"Taurine","amount":"1000 mg","spec":"Food-grade","basis":"ingredient mass"},{"name":"Magnesium","amount":"100 mg","spec":"Magnesium citrate; assay dependent","basis":"elemental mineral"},{"name":"Vitamin B1","amount":"1.1 mg","spec":"Thiamine hydrochloride","basis":"active vitamin"},{"name":"Vitamin B2","amount":"1.4 mg","spec":"Riboflavin","basis":"active vitamin"},{"name":"Vitamin B3","amount":"16 mg","spec":"Nicotinamide","basis":"active vitamin"}]', 'draft_formulation', 'Без стимуланти и без ATP като съставка. Работното име ATP Energy е заменено; не обещавай ATP съдържание.', 'S16 AESAN creatine assessment: https://efsa.onlinelibrary.wiley.com/doi/epdf/10.2903/fr.efsa.2024.FR-0046', 2340),
  ('NEW-035', 'Liposomal Vitamin C', 'Liposomal Formulations', null, 'Powder / sachet: Supplier-dependent serving', '[{"name":"Vitamin C","amount":"500 mg","spec":"Validated liposomal premix; active assay required","basis":"active vitamin"}]', 'technology_review', 'Само целеви активни дози. Няма определена маса на липозомния премикс или финална BOM. Нужни assay, състав, структура/размер, encapsulation efficiency, стабилност и regulatory оценка; лецитин + активка не доказва липозоми.', null, 2350),
  ('NEW-036', 'Liposomal Curcumin', 'Liposomal Formulations', null, 'Capsules / sachet: Supplier-dependent serving', '[{"name":"Curcuminoids","amount":"200 mg","spec":"Validated liposomal premix; active assay required","basis":"active compound"}]', 'technology_review', 'Само целеви активни дози. Няма определена маса на липозомния премикс или финална BOM. Нужни assay, състав, структура/размер, encapsulation efficiency, стабилност и regulatory оценка; лецитин + активка не доказва липозоми.', null, 2360),
  ('NEW-037', 'Liposomal Glutathione', 'Liposomal Formulations', null, 'Capsules / sachet: Supplier-dependent serving', '[{"name":"Reduced glutathione","amount":"250 mg","spec":"Validated liposomal premix; reduced/oxidised ratio control","basis":"active compound"}]', 'technology_review', 'Само целеви активни дози. Няма определена маса на липозомния премикс или финална BOM. Нужни assay, състав, структура/размер, encapsulation efficiency, стабилност и regulatory оценка; лецитин + активка не доказва липозоми.', null, 2370),
  ('NEW-038', 'Liposomal B-Complex', 'Liposomal Formulations', null, 'Supplier-developed premix: Supplier-dependent serving', '[{"name":"Vitamin B1","amount":"5 mg","spec":"Thiamine hydrochloride; encapsulation status to verify","basis":"active vitamin"},{"name":"Vitamin B2","amount":"2.8 mg","spec":"Riboflavin; encapsulation status to verify","basis":"active vitamin"},{"name":"Vitamin B3","amount":"16 mg","spec":"Nicotinamide; encapsulation status to verify","basis":"active vitamin"},{"name":"Vitamin B5","amount":"6 mg","spec":"Calcium D-pantothenate; encapsulation status to verify","basis":"active vitamin"},{"name":"Vitamin B6","amount":"1.4 mg","spec":"Pyridoxal-5-phosphate; encapsulation status to verify","basis":"active vitamin"},{"name":"Biotin","amount":"50 mcg","spec":"D-biotin; encapsulation status to verify","basis":"active vitamin"},{"name":"Folate","amount":"200 mcg","spec":"Calcium L-methylfolate; encapsulation status to verify","basis":"active vitamin"},{"name":"Vitamin B12","amount":"25 mcg","spec":"Methylcobalamin; encapsulation status to verify","basis":"active vitamin"}]', 'technology_review', 'Само целеви активни дози. Няма определена маса на липозомния премикс или финална BOM. Нужни assay, състав, структура/размер, encapsulation efficiency, стабилност и regulatory оценка; лецитин + активка не доказва липозоми.', null, 2380),
  ('NEW-039', 'Liposomal D3 + K2', 'Liposomal Formulations', null, 'Metered liquid or validated dry premix: Supplier-dependent serving', '[{"name":"Vitamin D3","amount":"25 mcg","spec":"Cholecalciferol; validated liposomal system","basis":"active vitamin"},{"name":"Vitamin K2","amount":"75 mcg","spec":"All-trans MK-7; validated liposomal system","basis":"active vitamin"}]', 'technology_review', 'Само целеви активни дози. Няма определена маса на липозомния премикс или финална BOM. Нужни assay, състав, структура/размер, encapsulation efficiency, стабилност и regulatory оценка; лецитин + активка не доказва липозоми. Vitamin K: преглед при антагонисти на витамин K.', null, 2390),
  ('NEW-040', 'Breast Enhancement', 'Women’s Health', null, 'Unspecified: No proposed intake', '[]', 'evidence_gap', 'Концепцията е запазена, но няма обоснована 5-компонентна формула с доказан ефект за уголемяване на бюст. Не предлагам хормонално активна смес с произволни дози. Нужни доказуемо задание, безопасност и клиничен план; не се заменя мълчаливо с Breast Comfort.', 'S17 Mayo Clinic breast enhancement: https://www.mayoclinic.org/healthy-lifestyle/womens-health/expert-answers/natural-breast-enhancement/faq-20057834', 2400),
  ('NEW-041', 'Acute Calm', 'Targeted Health Formulas', 'capsule', 'Target: 3 capsules; no rescue-dose claim', '[{"name":"L-Theanine","amount":"200 mg","spec":"Identity and purity assay","basis":"active compound"},{"name":"Lemon balm leaf extract","amount":"200 mg","spec":"Melissa officinalis; aqueous native DER 4:1 target","basis":"extract mass"},{"name":"Taurine","amount":"300 mg","spec":"Food-grade","basis":"ingredient mass"},{"name":"Magnesium","amount":"50 mg","spec":"Magnesium bisglycinate","basis":"elemental mineral"},{"name":"Vitamin B6","amount":"1.4 mg","spec":"Pyridoxal-5-phosphate","basis":"active vitamin"}]', 'draft_formulation', 'Не е лечение или спиране на паническа атака; начало на действие не е доказано. Без kava и стимуланти. Преглед при седативи/психотропни лекарства; сравни с Calm & Relax, NeuroBalance, NeuroCalm.', 'S18 NCCIH anxiety approaches: https://www.nccih.nih.gov/health/anxiety-and-complementary-health-approaches', 2410),
  ('NEW-042', 'Knee Support', 'Bones, Joints & Mobility', null, 'Powder / sachet: 1 measured daily serving', '[{"name":"Glucosamine sulfate","amount":"1500 mg","spec":"Expressed as glucosamine sulfate, not stabilising salt; calculate actual raw mass","basis":"active compound"},{"name":"Chondroitin sulfate","amount":"800 mg","spec":"Source, identity, purity and active assay","basis":"active compound"},{"name":"MSM","amount":"1500 mg","spec":"Methylsulfonylmethane","basis":"ingredient mass"},{"name":"Boswellia serrata gum resin extract","amount":"150 mg","spec":"65% total boswellic acids; not 65% AKBA","basis":"extract mass"},{"name":"Vitamin C","amount":"100 mg","spec":"Ascorbic acid","basis":"active vitamin"}]', 'draft_formulation', 'Различава се от стария нискодозов Joint Support по грамовия формат. Доказателствата за glucosamine/chondroitin са смесени; не обещава възстановяване на хрущял. Проверка на животински произход/алергени и взаимодействия с warfarin.', null, 2420),
  ('NEW-043', 'Back Comfort', 'Bones, Joints & Mobility', null, 'Powder / sachet: 1 measured daily serving', '[{"name":"MSM","amount":"1500 mg","spec":"Methylsulfonylmethane","basis":"ingredient mass"},{"name":"Magnesium","amount":"100 mg","spec":"Magnesium bisglycinate","basis":"elemental mineral"},{"name":"Boswellia serrata gum resin extract","amount":"200 mg","spec":"65% total boswellic acids; not AKBA","basis":"extract mass"},{"name":"Ginger rhizome extract","amount":"100 mg","spec":"5% gingerols","basis":"extract mass"},{"name":"Vitamin C","amount":"100 mg","spec":"Ascorbic acid","basis":"active vitamin"}]', 'draft_formulation', 'Самостоятелна мобилност/комфорт концепция; сместа не е изпитана за болки в гърба. Не заменя диагностиката на неврологични/структурни причини. Преглед при антикоагуланти, бъбречно увреждане.', null, 2430),
  ('NEW-044', 'Smokers Reset', 'Targeted Health Formulas', 'capsule', 'Target: 3 capsules', '[{"name":"N-Acetyl-L-cysteine","amount":"600 mg","spec":"NAC; target-country food/medicine classification to verify","basis":"ingredient mass"},{"name":"Vitamin C","amount":"200 mg","spec":"Ascorbic acid","basis":"active vitamin"},{"name":"Quercetin","amount":"200 mg","spec":"Identity and purity assay","basis":"active compound"},{"name":"Selenium","amount":"55 mcg","spec":"L-selenomethionine","basis":"elemental mineral"},{"name":"Vitamin B2","amount":"1.4 mg","spec":"Riboflavin","basis":"active vitamin"}]', 'supplier_review', 'Името Reset е за преглед: няма доказано възстановяване на вреди от пушене или профилактика на рак. Без beta-carotene и високи retinol дози. NAC изисква проверка по пазар и при нитрати; не замества отказването от тютюн.', 'S19 NCI lung cancer prevention: https://www.cancer.gov/types/lung/hp/lung-prevention-pdq', 2440),
  ('NEW-045', 'Senolytic Complex', 'Longevity & Cellular Health', null, 'Unspecified: No consumer dosing schedule', '[]', 'evidence_gap', 'Запазен отделно от Cellular Polyphenol. Няма валидирана ежедневна 5-компонентна сенолитична рецептура за този продукт. Fisetin/quercetin са изследователски кандидати, не одобрени тук дозировки. Не прехвърляй експериментални mg/kg пулсови режими от клинични изпитвания в каталог.', 'S20 Fisetin clinical trial: https://clinicaltrials.gov/study/NCT06431932', 2450),
  ('NEW-046', 'Male Vitality', 'Men’s Health & Sexual Wellness', 'capsule', 'Target: 3 capsules', '[{"name":"Maca root powder","amount":"1000 mg","spec":"Lepidium meyenii; gelatinized food-grade root powder","basis":"ingredient mass"},{"name":"Rhodiola rosea root/rhizome extract","amount":"200 mg","spec":"3% rosavins and 1% salidroside; HPLC","basis":"extract mass"},{"name":"Coenzyme Q10","amount":"100 mg","spec":"Ubiquinone","basis":"active compound"},{"name":"Zinc","amount":"10 mg","spec":"Zinc bisglycinate","basis":"elemental mineral"},{"name":"Vitamin B12","amount":"25 mcg","spec":"Methylcobalamin","basis":"active vitamin"}]', 'draft_formulation', 'По-широка жизненост; без tribulus/fenugreek/shilajit за разграничение от Libido/Testosterone. Не обещава повишение на тестостерона. Преглед при психотропни лекарства/биполярно разстройство и warfarin.', null, 2460)
  ) as v (code, name, category, format, pack, ingredients, status, notes, sources, sort_order)
  join public.catalog_categories c on c.name = v.category;

